def classify(n):
    if n == 0:
        return "zero"
    elif n == 1:
        return "v1"
    elif n == 2:
        return "v2"
    elif n == 3:
        return "v3"
    elif n == 4:
        return "v4"
    elif n == 5:
        return "v5"
    elif n == 6:
        return "v6"
    elif n == 7:
        return "v7"
    elif n == 8:
        return "v8"
    else:
        return "other"
